<?= $this->extend('layout') ?><?= $this->section('content') ?>
<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><h1>Asset List</h1><?php if(in_array(session()->get('role'),['admin','manager'],true)): ?><a class="btn" href="<?= site_url('assets/new') ?>">+ Asset Creation</a><?php endif ?></div>
<div class="cards"><?php foreach($counts as $label=>$count): ?><div class="stat"><small><?= esc($label) ?></small><strong><?= number_format($count) ?></strong></div><?php endforeach ?></div>
<div class="panel"><form method="get" action="<?= site_url('assets') ?>"><div class="toolbar"><input name="search" value="<?= esc($search) ?>" placeholder="Search all text columns…"><select name="perPage"><?php foreach([10,25,50,100] as $n): ?><option value="<?= $n ?>" <?= $perPage===$n?'selected':'' ?>><?= $n ?> per page</option><?php endforeach ?></select>
<?php foreach(['department'=>'Department','brand'=>'Brand','model'=>'Model','machine_type'=>'Machine Type','status'=>'Status','qr_status'=>'QR Status'] as $key=>$label): ?><select name="<?= $key ?>"><option value="">All <?= $label ?></option><?php if($key==='status'): foreach(['Active','Idle','Maintenance','Scrap'] as $v): ?><option <?= service('request')->getGet($key)===$v?'selected':'' ?>><?= $v ?></option><?php endforeach; elseif($key==='qr_status'): foreach(['Printed','Not Printed'] as $v): ?><option <?= service('request')->getGet($key)===$v?'selected':'' ?>><?= $v ?></option><?php endforeach; endif ?></select><?php endforeach ?>
<label class="hint">From <input type="date" name="from" value="<?= esc(service('request')->getGet('from')) ?>"></label><label class="hint">To <input type="date" name="to" value="<?= esc(service('request')->getGet('to')) ?>"></label><button class="btn">Apply</button><a class="btn gray" href="<?= site_url('assets') ?>">Reset</a></div></form>
<?php if(in_array(session()->get('role'),['admin','manager'],true)): ?><form method="post" action="<?= site_url('assets/bulk-delete') ?>" onsubmit="return confirm('Move selected assets to deleted records?')"><?= csrf_field() ?><?php endif ?>
<div class="table-wrap"><table><thead><tr><?php if(in_array(session()->get('role'),['admin','manager'],true)): ?><th><input type="checkbox" id="all"></th><?php endif ?><th>S.No</th><?php foreach(['created_at'=>'Created Date','asset_id'=>'Asset ID','serial_no'=>'Serial No','department'=>'Department','brand'=>'Brand','model'=>'Model','machine_type'=>'Machine Type','installation_date'=>'Calibration','status'=>'Status','qr_status'=>'QR Status'] as $k=>$label): ?><th><a href="<?= current_url().'?'.http_build_query(array_merge($_GET,['sort'=>$k,'direction'=>$sort===$k&&$direction==='ASC'?'DESC':'ASC','page'=>1])) ?>"><?= esc($label) ?> <?= $sort===$k?($direction==='ASC'?'↑':'↓'):'' ?></a></th><?php endforeach ?><th>Action</th></tr></thead><tbody>
<?php if(!$rows): ?><tr><td colspan="14">No assets found.</td></tr><?php endif ?>
<?php foreach($rows as $i=>$a): ?><tr><?php if(in_array(session()->get('role'),['admin','manager'],true)): ?><td><input type="checkbox" name="ids[]" value="<?= $a['id'] ?>" class="row-check"></td><?php endif ?><td><?= ($page-1)*$perPage+$i+1 ?></td><td><?= date('d-m-Y',strtotime($a['created_at'])) ?></td><td><strong><?= esc($a['asset_id']) ?></strong></td><td><?= esc($a['serial_no']??'—') ?></td><td><?= esc($a['department']??'—') ?></td><td><?= esc($a['brand']??'—') ?></td><td><?= esc($a['model']??'—') ?></td><td><?= esc($a['machine_type']??'—') ?></td><td><?= $a['installation_date']?date('d-m-Y',strtotime($a['installation_date'])):'Not Recorded' ?></td><td><span class="badge <?= esc($a['status']) ?>"><?= esc($a['status']) ?></span></td><td><?= esc($a['qr_status']) ?><?= $a['qr_printed_at']?'<br><small>'.esc(date('d-m-Y H:i',strtotime($a['qr_printed_at']))).'</small>':'' ?></td><td><div class="actions"><?php if(in_array(session()->get('role'),['admin','manager'],true)): ?><a class="btn" href="<?= site_url('assets/'.$a['id'].'/edit') ?>">Edit</a><button class="btn red" type="button" onclick="deleteAsset(<?= $a['id'] ?>)">Delete</button><?php else: ?><span class="muted">View only</span><?php endif ?></div></td></tr><?php endforeach ?></tbody></table></div>
<?php if(in_array(session()->get('role'),['admin','manager'],true)): ?><button class="btn red" type="submit" style="margin-top:12px">Delete selected</button></form><?php endif ?>
<div class="pagination"><span>Showing <?= $total?($page-1)*$perPage+1:0 ?>–<?= min($page*$perPage,$total) ?> of <?= number_format($total) ?> records</span><div><?php if($page>1): ?><a href="<?= current_url().'?'.http_build_query(array_merge($_GET,['page'=>$page-1])) ?>">Previous</a><?php endif ?> <strong>Page <?= $page ?> / <?= max(1,ceil($total/$perPage)) ?></strong> <?php if($page*$perPage<$total): ?><a href="<?= current_url().'?'.http_build_query(array_merge($_GET,['page'=>$page+1])) ?>">Next</a><?php endif ?></div></div>
</div>
<form id="delete-form" method="post"><?= csrf_field() ?></form><script>document.getElementById('all')?.addEventListener('change',e=>document.querySelectorAll('.row-check').forEach(c=>c.checked=e.target.checked));function deleteAsset(id){if(confirm('Delete this asset? It will be soft-deleted.')){const f=document.getElementById('delete-form');f.action='<?= site_url('assets') ?>/'+id+'/delete';f.submit()}}</script>
<?= $this->endSection() ?>
